// Apify 替代适配: Remotive 免费职位API -> 模板字段(id/title/company/city/applyUrl), 截前8条
const data = $input.first().json.jobs || [];
const pick = data.slice(0, 8);
return pick.map(j => ({ json: { id: String(j.id), title: j.title, company: j.company_name,
  city: j.candidate_required_location || 'Worldwide', applyUrl: j.url } }));

// Google Sheets 替代: 本地 JSON 台账; 空表输出 1 空 item (=Always Output Data, 防 0-item 断链)
const fs = require('fs');
let rows = [];
try { rows = JSON.parse(fs.readFileSync('C:\\Users\\Administrator\\.easyclaw\\workspace\\n8n-lesson-crew\\state\\factory\\20683-l2\\seen.json', 'utf8')); } catch(e) {}
if (!Array.isArray(rows)) rows = [];
if (rows.length === 0) rows = [{}];
return rows.map(r => ({ json: r }));

const cfg = $('Search Settings').first().json;
const seenRows = $('Get Seen IDs').all();
const fetchedItems = $('Fetch Jobs').all();

  const seen = new Set(seenRows.map(i => String(i.json.id || '')).filter(Boolean));
  const fetched = fetchedItems.map(i => i.json).filter(j => j && j.id);
  const jobs = [];
  const ids = new Set();
  for (const j of fetched) {
    const id = String(j.id);
    if (seen.has(id) || ids.has(id)) continue;
    ids.add(id);
    jobs.push({ id, title: j.title, company: j.company, location: j.city || j.country || 'Remote', applyUrl: j.applyUrl });
  }
  const list = jobs.map(j => j.id + ' | ' + j.title + ' | ' + j.company + ' | ' + j.location).join('\n');
  const prompt = 'You rate job fit. Candidate profile:\n' + cfg.profile + '\n\nFor each job below (format: id | title | company | location) give an integer score 0-10 for how well it fits the candidate, and a reason of at most 12 words. Only title, company and location are known, so judge on those. Reply with ONLY a JSON array like [{"id":"...","score":7,"reason":"..."}], one entry per job, no other text.\n\nJobs:\n' + list;
  return [{ json: { jobs, count: jobs.length, prompt, model: cfg.claudeModel, keywords: cfg.keywords, topN: cfg.topN } }];

// Claude->DeepSeek 响应适配: choices[0].message.content -> content[0].text (Merge Scores 原样不动)
const j = $input.first().json;
const text = (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
return [{ json: { model: j.model, content: [{ type: 'text', text }] } }];

const prep = $('Filter & Prep').first().json;
const inputJson = $input.first().json;

  const scores = {};
  try {
    const txt = inputJson.content[0].text;
    const arr = JSON.parse(txt.match(/\[[\s\S]*\]/)[0]);
    for (const s of arr) scores[String(s.id)] = { score: Number(s.score), reason: String(s.reason || '') };
  } catch (e) {}
  const now = new Date().toISOString();
  const rows = prep.jobs
    .filter(j => scores[j.id] && !isNaN(scores[j.id].score))
    .map(j => ({ ...j, score: scores[j.id].score, reason: scores[j.id].reason }));
  if (!rows.length) throw new Error('Claude returned no readable scores. Check the Score with Claude node output; nothing was logged, so these jobs will be retried on the next run.');
  rows.sort((a, b) => b.score - a.score);
  const topN = Number(prep.topN) || 5;
  return rows.map((r, i) => ({ json: { ...r, sent: i < topN, status: '', loggedAt: now, keywords: prep.keywords, total: rows.length } }));

const allRows = $input.all();

  const rows = allRows.map(i => i.json).filter(r => r.sent);
  const total = rows.length ? rows[0].total : 0;
  const label = rows.length ? (rows[0].keywords || 'all jobs') : 'all jobs';
  const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const sc = r => (r.score === '' ? '?' : r.score) + '/10';
  const header = 'Top ' + rows.length + ' of ' + total + ' new job(s) for "' + label + '":\n\n';
  const lines = rows.map(r => '• [' + sc(r) + '] ' + r.title + ' @ ' + r.company + ' (' + r.location + ')\n' + r.reason + '\n' + r.applyUrl);
  let out = header;
  let shown = 0;
  for (const l of lines) {
    if ((out + l + '\n\n').length > 3900) break;
    out += l + '\n\n';
    shown++;
  }
  const text = shown < lines.length ? out.trimEnd() + '\n\n+' + (lines.length - shown) + ' more' : out.trimEnd();
  const html = '<h3>Top ' + rows.length + ' of ' + total + ' new job(s) for "' + esc(label) + '"</h3><ul>' +
    rows.map(r => '<li><b>[' + sc(r) + ']</b> <a href="' + esc(r.applyUrl) + '">' + esc(r.title) + '</a> @ ' + esc(r.company) + ' (' + esc(r.location) + ')<br>' + esc(r.reason) + '</li>').join('') + '</ul>';
  return [{ json: { text, html, subject: 'Job alert: ' + label, count: rows.length } }];

// Google Sheets 替代: 台账回写本地 JSON(全部打分行) + 更新 seen(供下轮去重)
const fs = require('fs');
const rows = $input.all().map(i => i.json);
let seen = [];
try { seen = JSON.parse(fs.readFileSync('C:\\Users\\Administrator\\.easyclaw\\workspace\\n8n-lesson-crew\\state\\factory\\20683-l2\\seen.json', 'utf8')); } catch(e) {}
if (!Array.isArray(seen)) seen = [];
const ids = new Set(seen.map(r => String(r.id || '')));
for (const r of rows) { if (!ids.has(String(r.id))) { seen.push({ id: r.id, score: r.score, loggedAt: r.loggedAt }); ids.add(String(r.id)); } }
fs.writeFileSync('C:\\Users\\Administrator\\.easyclaw\\workspace\\n8n-lesson-crew\\state\\factory\\20683-l2\\seen.json', JSON.stringify(seen, null, 1));
fs.writeFileSync('C:\\Users\\Administrator\\.easyclaw\\workspace\\n8n-lesson-crew\\state\\factory\\20683-l2\\log.json', JSON.stringify(rows, null, 1));
return [{ json: { logged: rows.length, seenTotal: seen.length } }];

const filterPrepFirst = $('Filter & Prep').first().json;

  const label = filterPrepFirst.keywords || 'all jobs';
  const text = 'No new jobs today for "' + label + '".';
  return [{ json: { text, html: '<p>' + text.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</p>', subject: 'Job alert: ' + label, count: 0 } }];

// 发送结果整型 (跟在 Send Feishu HTTP 后面)
const j = $input.first().json;
return [{ json: { channel: 'feishu', sent: j.code === 0, messageId: j.data && j.data.message_id } }];

const items = n => { try { return $(n).all().map(i => i.json); } catch(e) { return []; } };
let prepCount = -1; try { prepCount = $('Filter & Prep').first().json.count; } catch(e) {}
const merged = items('Merge Scores');
const lg = items('Log to Sheet');
const fs_ = items('Send Feishu Result');
let text = null;
try { text = $('Build Message').first().json.text; } catch(e) {}
if (!text) { try { text = $('No New Jobs Message').first().json.text; } catch(e) {} }
return [{ json: { e2e: true, prepCount, mergedCount: merged.length,
  logged: lg.length ? lg[0].logged : -1, seenTotal: lg.length ? lg[0].seenTotal : -1,
  feishuSent: fs_.length ? fs_[0].sent : null, feishuMsgId: fs_.length ? fs_[0].messageId : null,
  sentRows: merged.filter(r => r.sent).length,
  textHead: (text || '').slice(0, 80) } }];
